#!/usr/bin/env python3

# Some portions generated by Codex

from __future__ import annotations

import importlib.util
import json
import tempfile
import unittest
from pathlib import Path
from types import SimpleNamespace


REPOSITORY_ROOT = Path(__file__).resolve().parents[1]
SCRIPT = REPOSITORY_ROOT / "scripts" / "run-packed-synthetic-campaign.py"


def load_campaign_module():
    spec = importlib.util.spec_from_file_location("packed_synthetic_campaign", SCRIPT)
    if spec is None or spec.loader is None:
        raise AssertionError(f"unable to load {SCRIPT}")
    module = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(module)
    return module


def write_json(path: Path, value: object) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(json.dumps(value) + "\n", encoding="utf-8")


def succeeded(path: Path) -> None:
    write_json(path, {"formatVersion": 1, "outcome": "succeeded"})


def write_factor(
    results: Path,
    factor: int,
    completion: str,
    times: list[float],
    allocations: list[float],
) -> None:
    audit = results / f"factor-{factor}.audit.json"
    write_json(
        audit,
        {
            "formatVersion": 1,
            "kind": "packed-cascades-search-audit",
            "factors": factor,
            "completionStatus": completion,
            "exact": completion == "EXACT_COMPLETE",
            "retainedBytes": 1234,
        },
    )
    succeeded(audit.with_suffix(".status.json"))
    write_timing_lane(results, factor, "cold", 0, times[:1], allocations[:1])
    write_timing_lane(results, factor, "saturated", 20, times[1:], allocations[1:])


def write_timing_lane(
    results: Path,
    factor: int,
    lane: str,
    warmups: int,
    times: list[float],
    allocations: list[float],
) -> None:
    jmh = results / f"factor-{factor}.{lane}.jmh.json"
    write_json(
        jmh,
        [
            {
                "benchmark": (
                    "org.eclipse.rdf4j.query.algebra.evaluation.optimizer.cascades."
                    "packed.PackedCascadesSearchBenchmark.plan"
                ),
                "mode": "ss",
                "threads": 1,
                "forks": 1,
                "warmupIterations": warmups,
                "measurementIterations": len(times),
                "params": {"factors": str(factor)},
                "primaryMetric": {
                    "rawData": [times],
                    "scoreUnit": "ms/op",
                },
                "secondaryMetrics": {
                    "gc.alloc.rate.norm": {
                        "rawData": [allocations],
                        "scoreUnit": "B/op",
                    }
                },
            }
        ],
    )
    succeeded(jmh.with_suffix(".status.json"))


class PackedSyntheticCampaignTest(unittest.TestCase):

    def setUp(self) -> None:
        self.campaign = load_campaign_module()

    def test_jmh_commands_keep_process_cold_and_saturated_lanes_distinct(self) -> None:
        args = SimpleNamespace(jar=Path("benchmark.jar"))

        cold = self.campaign.jmh_command(
            args,
            4,
            Path("cold.json"),
            warmup_iterations=0,
            measurement_iterations=1,
        )
        saturated = self.campaign.jmh_command(
            args,
            4,
            Path("saturated.json"),
            warmup_iterations=20,
            measurement_iterations=7,
        )

        self.assertEqual("0", cold[cold.index("-wi") + 1])
        self.assertEqual("1", cold[cold.index("-i") + 1])
        self.assertEqual("20", saturated[saturated.index("-wi") + 1])
        self.assertEqual("7", saturated[saturated.index("-i") + 1])

    def test_summary_uses_only_warmed_lane_for_saturated_percentiles(self) -> None:
        with tempfile.TemporaryDirectory() as directory:
            results = Path(directory)
            audit = results / "factor-4.audit.json"
            write_json(
                audit,
                {
                    "formatVersion": 1,
                    "kind": "packed-cascades-search-audit",
                    "factors": 4,
                    "completionStatus": "EXACT_COMPLETE",
                    "exact": True,
                    "retainedBytes": 1234,
                },
            )
            succeeded(audit.with_suffix(".status.json"))
            write_timing_lane(results, 4, "cold", 0, [90.0], [16_000_000])
            write_timing_lane(
                results,
                4,
                "saturated",
                20,
                [0.40, 0.35, 0.30, 0.32, 0.31, 0.33, 0.34],
                [100_000, 98_000, 99_000, 101_000, 97_000, 96_000, 95_000],
            )

            summary = self.campaign.summarize_campaign(results, (4,), 7, 20)

            record = summary["factors"][0]
            self.assertEqual(90.0, record["coldMillis"])
            self.assertEqual(0.40, record["saturatedP95Millis"])
            self.assertEqual(1, record["coldSampleCount"])
            self.assertEqual(7, record["saturatedSampleCount"])
            self.assertFalse(summary["fourFactorColdGatePass"])
            self.assertTrue(summary["fourFactorSaturatedGatePass"])

    def test_summary_reports_cold_and_saturated_gates_and_completion(self) -> None:
        with tempfile.TemporaryDirectory() as directory:
            results = Path(directory)
            write_factor(
                results,
                4,
                "EXACT_COMPLETE",
                [90.0, 0.40, 0.35, 0.30, 0.32, 0.31, 0.33, 0.34],
                [16_000_000, 100_000, 98_000, 99_000, 101_000, 97_000, 96_000, 95_000],
            )
            write_factor(
                results,
                8,
                "INCOMPLETE_RESOURCE_LIMIT",
                [91.0, 4.0, 3.5, 3.0, 3.2, 3.1, 3.3, 3.4],
                [
                    17_000_000,
                    1_000_000,
                    980_000,
                    990_000,
                    1_010_000,
                    970_000,
                    960_000,
                    950_000,
                ],
            )

            summary = self.campaign.summarize_campaign(results, (4, 8), 7)

            self.assertEqual("complete", summary["status"])
            self.assertEqual([4], summary["exactFactors"])
            self.assertEqual([8], summary["incompleteFactors"])
            self.assertEqual(90.0, summary["factors"][0]["allSampleP95Millis"])
            self.assertEqual(0.40, summary["factors"][0]["saturatedP95Millis"])
            self.assertEqual(
                16_000_000,
                summary["factors"][0]["allSampleP95AllocationBytes"],
            )
            self.assertEqual(
                101_000,
                summary["factors"][0]["saturatedP95AllocationBytes"],
            )
            self.assertFalse(summary["fourFactorAllSampleGatePass"])
            self.assertTrue(summary["fourFactorSaturatedGatePass"])
            self.assertFalse(summary["eightFactorAllSampleGatePass"])
            self.assertTrue(summary["eightFactorSaturatedGatePass"])

    def test_summary_keeps_missing_or_stale_factor_cells_explicit(self) -> None:
        with tempfile.TemporaryDirectory() as directory:
            results = Path(directory)
            write_factor(
                results,
                4,
                "EXACT_COMPLETE",
                [1.0] * 8,
                [100_000] * 8,
            )
            audit = results / "factor-4.audit.json"
            write_json(audit, json.loads(audit.read_text()) | {"factors": 5})

            summary = self.campaign.summarize_campaign(results, (4, 8), 7)

            self.assertEqual("incomplete", summary["status"])
            self.assertEqual(0, summary["completedFactorCount"])
            self.assertEqual(["audit-stale"], summary["factors"][0]["issues"])
            self.assertEqual(
                ["audit-missing", "cold-jmh-missing", "saturated-jmh-missing"],
                summary["factors"][1]["issues"],
            )

    def test_summary_rejects_mismatched_saturated_warmup_identity(self) -> None:
        with tempfile.TemporaryDirectory() as directory:
            results = Path(directory)
            write_factor(
                results,
                4,
                "EXACT_COMPLETE",
                [1.0] * 8,
                [100_000] * 8,
            )

            summary = self.campaign.summarize_campaign(results, (4,), 7, 19)

            self.assertEqual("incomplete", summary["status"])
            self.assertEqual(
                ["saturated-jmh-stale"],
                summary["factors"][0]["issues"],
            )

    def test_summary_preserves_exact_audit_and_cold_lane_when_saturated_times_out(
        self,
    ) -> None:
        with tempfile.TemporaryDirectory() as directory:
            results = Path(directory)
            audit = results / "factor-128.audit.json"
            write_json(
                audit,
                {
                    "formatVersion": 1,
                    "kind": "packed-cascades-search-audit",
                    "factors": 128,
                    "completionStatus": "EXACT_COMPLETE",
                    "exact": True,
                    "retainedBytes": 39_662_112,
                },
            )
            succeeded(audit.with_suffix(".status.json"))
            write_timing_lane(results, 128, "cold", 0, [19_801.0], [65_135_520])
            saturated = results / "factor-128.saturated.jmh.json"
            write_json(saturated, [])
            write_json(saturated.with_suffix(".status.json"), {"outcome": "timeout"})

            summary = self.campaign.summarize_campaign(results, (128,), 20, 20)

            record = summary["factors"][0]
            self.assertEqual("incomplete", record["status"])
            self.assertEqual(["saturated-jmh-timeout"], record["issues"])
            self.assertEqual("EXACT_COMPLETE", record["completionStatus"])
            self.assertTrue(record["exact"])
            self.assertEqual(19_801.0, record["coldMillis"])
            self.assertEqual([128], summary["exactFactors"])


if __name__ == "__main__":
    unittest.main()
